import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  images: {
    remotePatterns: [
      { protocol: "https", hostname: "*.supabase.co" },
    ],
  },
};

export default nextConfig;

import { FlatCompat } from "@eslint/eslintrc";

const compat = new FlatCompat({ baseDirectory: import.meta.dirname });

const eslintConfig = [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    ignores: [".next/**", "out/**", "build/**", "next-env.d.ts", "node_modules/**"],
  },
];

export default eslintConfig;

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

/// <reference types="next" />
/// <reference types="next/image-types/global" />
/// <reference path="./.next/types/routes.d.ts" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

{
  "crons": [
    {
      "path": "/api/cron/expire-subscriptions",
      "schedule": "15 0 * * *"
    }
  ]
}

import { chromium } from "playwright";

// Triggered after the dedicated RAWI E2E account is configured.

const base = process.env.RAWI_BASE_URL || "https://rawi-five.vercel.app";
const email = process.env.RAWI_E2E_EMAIL;
const password = process.env.RAWI_E2E_PASSWORD;
if (!email || !password) throw new Error("RAWI_E2E_EMAIL and RAWI_E2E_PASSWORD are required.");

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
try {
  await page.goto(`${base}/login`, { waitUntil: "domcontentloaded", timeout: 30000 });
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Password").fill(password);
  await page.getByRole("button", { name: "Sign in" }).click();

  try {
    await page.waitForFunction(() => !window.location.pathname.includes("/login") || Boolean(document.querySelector('[class*="text-red"], [role="alert"]')), null, { timeout: 30000 });
  } catch {
    const body = (await page.locator("body").innerText()).replace(/\s+/g, " ").slice(0, 800);
    throw new Error(`Sign-in did not leave /login within 30s. Current URL: ${page.url()}. Page says: ${body}`);
  }

  if (page.url().includes("/login")) {
    const body = (await page.locator("body").innerText()).replace(/\s+/g, " ").slice(0, 800);
    throw new Error(`RAWI sign-in failed. Page says: ${body}`);
  }

  if (page.url().includes("/onboarding")) {
    throw new Error("E2E account signed in but has no RAWI workspace. Complete onboarding once for the test account.");
  }

  for (const route of ["/dashboard", "/projects", "/settings"]) {
    const response = await page.goto(`${base}${route}`, { waitUntil: "domcontentloaded", timeout: 30000 });
    if (!response || !response.ok()) throw new Error(`${route} returned ${response?.status() ?? "no response"}`);
    if (page.url().includes("/login")) throw new Error(`${route} unexpectedly redirected to login.`);
    if (page.url().includes("/onboarding")) throw new Error(`${route} redirected to onboarding; complete workspace setup for the E2E account.`);
  }

  console.log("RAWI authenticated E2E smoke passed.");
} finally {
  await browser.close();
}

const base=(process.env.RAWI_BASE_URL||"https://rawi-five.vercel.app").replace(/\/$/,"");
const checks=[
  {name:"Home",path:"/",expect:[200]},
  {name:"Login",path:"/login",expect:[200]},
  {name:"Protected dashboard",path:"/dashboard",expect:[200,307,308]},
  {name:"Protected projects",path:"/projects",expect:[200,307,308]},
  {name:"Protected settings",path:"/settings",expect:[200,307,308]},
  {name:"Monitoring endpoint method guard",path:"/api/client-error",method:"GET",expect:[400,404,405]},
];
let failed=0;
for(const check of checks){const started=performance.now();try{const response=await fetch(`${base}${check.path}`,{method:check.method||"GET",redirect:"manual",headers:{"user-agent":"RAWI-production-smoke/1.0"}});const ms=Math.round(performance.now()-started);const ok=check.expect.includes(response.status);console.log(`${ok?"✓":"✗"} ${check.name}: ${response.status} (${ms} ms)`);if(!ok)failed++}catch(error){failed++;console.error(`✗ ${check.name}: ${error instanceof Error?error.message:String(error)}`)}}
if(failed){console.error(`\n${failed} smoke check${failed===1?"":"s"} failed.`);process.exit(1)}
console.log(`\nAll ${checks.length} RAWI production smoke checks passed.`);

-- RAWI performance: collapse dashboard metrics into one indexed database call.

create index if not exists idx_projects_workspace_created
  on public.projects (workspace_id, created_at desc);
create index if not exists idx_media_project_type
  on public.media (project_id, media_type);
create index if not exists idx_galleries_project_status
  on public.galleries (project_id, status);
create index if not exists idx_downloads_gallery
  on public.downloads (gallery_id);
create index if not exists idx_favorites_gallery
  on public.favorites (gallery_id);
create index if not exists idx_gallery_comments_gallery_status
  on public.gallery_comments (gallery_id, status);

create or replace function public.rawi_dashboard_stats(target_workspace_id uuid)
returns jsonb
language sql
security definer
set search_path = public
stable
as $$
  with allowed as (
    select public.is_workspace_member(target_workspace_id) as ok
  ),
  p as (
    select id, status
    from public.projects
    where workspace_id = target_workspace_id
      and (select ok from allowed)
  ),
  g as (
    select g.id, g.project_id, g.status
    from public.galleries g
    join p on p.id = g.project_id
  ),
  feedback as (
    select g.project_id, count(*)::int as new_count
    from public.gallery_comments c
    join g on g.id = c.gallery_id
    where c.status = 'new'
    group by g.project_id
  )
  select jsonb_build_object(
    'project_count', (select count(*)::int from p),
    'photo_count', (
      select count(*)::int from public.media m join p on p.id = m.project_id where m.media_type = 'image'
    ),
    'published_count', (select count(*)::int from g where status = 'published'),
    'download_count', (
      select count(*)::int from public.downloads d join g on g.id = d.gallery_id
    ),
    'favorite_count', (
      select count(*)::int from public.favorites f join g on g.id = f.gallery_id
    ),
    'new_feedback_count', (select coalesce(sum(new_count),0)::int from feedback),
    'feedback_by_project', coalesce((select jsonb_object_agg(project_id::text,new_count) from feedback), '{}'::jsonb)
  )
  where (select ok from allowed);
$$;

revoke all on function public.rawi_dashboard_stats(uuid) from public;
grant execute on function public.rawi_dashboard_stats(uuid) to authenticated;

alter table public.galleries
  add column if not exists theme text not null default 'clean'
  check (theme in ('clean','dark','editorial'));

create table if not exists public.billing_payment_attempts (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  plan text not null check (plan in ('creator','pro')),
  amount integer not null check (amount > 0),
  currency_code text not null default 'AED' check (currency_code = 'AED'),
  status text not null default 'requires_payment_instrument' check (status in ('requires_payment_instrument','requires_user_action','pending','completed','failed','canceled')),
  ziina_payment_intent_id text not null unique,
  test_mode boolean not null default false,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists billing_payment_attempts_workspace_created_idx
  on public.billing_payment_attempts (workspace_id, created_at desc);

alter table public.billing_payment_attempts enable row level security;
revoke all on table public.billing_payment_attempts from anon, authenticated;

create or replace function public.set_billing_payment_attempt_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists set_billing_payment_attempt_updated_at on public.billing_payment_attempts;
create trigger set_billing_payment_attempt_updated_at
before update on public.billing_payment_attempts
for each row execute function public.set_billing_payment_attempt_updated_at();

revoke all on function public.set_billing_payment_attempt_updated_at() from public, anon, authenticated;

create or replace function public.activate_ziina_payment(p_payment_intent_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  payment_attempt public.billing_payment_attempts%rowtype;
  existing_period_end timestamptz;
  next_period_end timestamptz;
  storage_limit bigint;
begin
  select * into payment_attempt
  from public.billing_payment_attempts
  where ziina_payment_intent_id = p_payment_intent_id
  for update;

  if not found then raise exception 'Unknown payment intent'; end if;
  if payment_attempt.completed_at is not null then
    return jsonb_build_object('already_applied', true, 'plan', payment_attempt.plan);
  end if;

  storage_limit := case payment_attempt.plan
    when 'creator' then 200::bigint * 1024 * 1024 * 1024
    when 'pro' then 500::bigint * 1024 * 1024 * 1024
    else null
  end;
  if storage_limit is null then raise exception 'Invalid paid plan'; end if;

  select current_period_end into existing_period_end
  from public.subscriptions
  where workspace_id = payment_attempt.workspace_id
  for update;

  next_period_end := greatest(coalesce(existing_period_end, now()), now()) + interval '30 days';

  update public.workspaces
  set plan = payment_attempt.plan, storage_limit_bytes = storage_limit
  where id = payment_attempt.workspace_id;
  if not found then raise exception 'Unknown workspace'; end if;

  insert into public.subscriptions (
    workspace_id, plan, status, current_period_end, ziina_payment_intent_id, provider
  ) values (
    payment_attempt.workspace_id, payment_attempt.plan, 'active', next_period_end,
    payment_attempt.ziina_payment_intent_id, 'ziina'
  )
  on conflict (workspace_id) do update set
    plan = excluded.plan,
    status = excluded.status,
    current_period_end = excluded.current_period_end,
    ziina_payment_intent_id = excluded.ziina_payment_intent_id,
    provider = excluded.provider,
    updated_at = now();

  update public.billing_payment_attempts
  set status = 'completed', completed_at = now()
  where id = payment_attempt.id;

  return jsonb_build_object('already_applied', false, 'plan', payment_attempt.plan, 'current_period_end', next_period_end);
end;
$$;

revoke all on function public.activate_ziina_payment(text) from public, anon, authenticated;
grant execute on function public.activate_ziina_payment(text) to service_role;

create table if not exists public.discount_redemptions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  code_key text not null,
  discount_percentage smallint not null check (discount_percentage in (10, 50, 100)),
  plan text not null check (plan in ('creator', 'pro')),
  original_amount integer not null check (original_amount > 0),
  final_amount integer not null check (final_amount >= 0),
  status text not null default 'reserved' check (status in ('reserved', 'redeemed', 'failed')),
  ziina_payment_intent_id text unique,
  created_at timestamptz not null default now(),
  redeemed_at timestamptz
);

create unique index if not exists discount_redemptions_workspace_active_idx
  on public.discount_redemptions (workspace_id)
  where status in ('reserved', 'redeemed');
create index if not exists discount_redemptions_code_status_idx
  on public.discount_redemptions (code_key, status);

alter table public.discount_redemptions enable row level security;
revoke all on table public.discount_redemptions from anon, authenticated;

alter table public.billing_payment_attempts
  add column if not exists original_amount integer,
  add column if not exists discount_percentage smallint not null default 0,
  add column if not exists discount_redemption_id uuid references public.discount_redemptions(id);

create or replace function public.claim_rawi_discount(
  p_workspace_id uuid,
  p_user_id uuid,
  p_code_key text,
  p_discount_percentage smallint,
  p_max_uses integer,
  p_plan text,
  p_original_amount integer,
  p_final_amount integer
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  redemption public.discount_redemptions%rowtype;
  current_uses integer;
  next_period_end timestamptz;
  storage_limit bigint;
begin
  if p_discount_percentage not in (10, 50, 100)
     or p_plan not in ('creator', 'pro')
     or p_original_amount <= 0
     or p_final_amount < 0 then
    raise exception 'Invalid discount request';
  end if;

  if not exists (
    select 1 from public.workspace_members
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and role in ('owner', 'admin')
  ) then raise exception 'Not authorized'; end if;

  perform pg_advisory_xact_lock(hashtext(p_code_key));

  update public.discount_redemptions
    set status = 'failed'
    where status = 'reserved' and created_at < now() - interval '1 hour';

  if exists (
    select 1 from public.discount_redemptions
    where workspace_id = p_workspace_id and status in ('reserved', 'redeemed')
  ) then raise exception 'A discount was already used for this workspace'; end if;

  select count(*) into current_uses
  from public.discount_redemptions
  where code_key = p_code_key and status in ('reserved', 'redeemed');
  if current_uses >= p_max_uses then raise exception 'This code has reached its usage limit'; end if;

  insert into public.discount_redemptions (
    workspace_id, user_id, code_key, discount_percentage, plan,
    original_amount, final_amount, status
  ) values (
    p_workspace_id, p_user_id, p_code_key, p_discount_percentage, p_plan,
    p_original_amount, p_final_amount,
    case when p_discount_percentage = 100 then 'redeemed' else 'reserved' end
  ) returning * into redemption;

  if p_discount_percentage = 100 then
    storage_limit := case p_plan
      when 'creator' then 200::bigint * 1024 * 1024 * 1024
      when 'pro' then 500::bigint * 1024 * 1024 * 1024
    end;
    select greatest(coalesce(current_period_end, now()), now()) + interval '30 days'
      into next_period_end
    from public.subscriptions where workspace_id = p_workspace_id;
    next_period_end := coalesce(next_period_end, now() + interval '30 days');

    update public.workspaces
      set plan = p_plan, storage_limit_bytes = storage_limit
      where id = p_workspace_id;

    insert into public.subscriptions (
      workspace_id, plan, status, current_period_end, provider
    ) values (
      p_workspace_id, p_plan, 'active', next_period_end, 'promo'
    ) on conflict (workspace_id) do update set
      plan = excluded.plan,
      status = excluded.status,
      current_period_end = excluded.current_period_end,
      ziina_payment_intent_id = null,
      provider = 'promo',
      updated_at = now();

    update public.discount_redemptions
      set redeemed_at = now() where id = redemption.id;
  end if;

  return jsonb_build_object(
    'redemption_id', redemption.id,
    'discount_percentage', redemption.discount_percentage,
    'final_amount', redemption.final_amount,
    'activated', p_discount_percentage = 100,
    'current_period_end', next_period_end
  );
end;
$$;

revoke all on function public.claim_rawi_discount(uuid, uuid, text, smallint, integer, text, integer, integer) from public, anon, authenticated;
grant execute on function public.claim_rawi_discount(uuid, uuid, text, smallint, integer, text, integer, integer) to service_role;

-- RAWI Phase 3 performance indexes for common sorted lookups.

create index if not exists idx_clients_workspace_name
  on public.clients (workspace_id, name);

create index if not exists idx_gallery_sections_gallery_sort
  on public.gallery_sections (gallery_id, sort_order);

create index if not exists idx_media_project_sort_created
  on public.media (project_id, sort_order, created_at);

create index if not exists idx_media_section_sort
  on public.media (gallery_section_id, sort_order);

create index if not exists idx_gallery_comments_gallery_created
  on public.gallery_comments (gallery_id, created_at desc);

create index if not exists idx_gallery_approvals_gallery_approved
  on public.gallery_approvals (gallery_id, approved_at desc);

alter table public.workspaces
add column if not exists whatsapp_url text;

alter table public.workspaces
drop constraint if exists workspaces_whatsapp_url_http;

alter table public.workspaces
add constraint workspaces_whatsapp_url_http
check (whatsapp_url is null or whatsapp_url ~ '^https?://');

-- RAWI initial schema
-- Every user-owned table is scoped through workspace ownership + RLS.
-- Nothing here trusts the frontend: policies check auth.uid() against
-- workspace_members, never a client-supplied user id.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------------
-- profiles: 1:1 with auth.users, created automatically on signup
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  email text not null,
  avatar_url text,
  preferred_language text not null default 'en' check (preferred_language in ('en', 'ar')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.profiles enable row level security;

create policy "profiles: read own" on public.profiles
  for select using (auth.uid() = id);
create policy "profiles: update own" on public.profiles
  for update using (auth.uid() = id);

-- Auto-create a profile row when a new auth user is confirmed.
create function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, new.raw_user_meta_data->>'full_name');
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- ---------------------------------------------------------------------------
-- workspaces + membership (studio/team-ready from day one)
-- ---------------------------------------------------------------------------
create table public.workspaces (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles(id) on delete cascade,
  name text not null,
  slug text not null unique,
  logo_url text,
  accent_color text not null default '#FFD400',
  plan text not null default 'free' check (plan in ('free', 'creator', 'pro', 'studio')),
  storage_limit_bytes bigint not null default 5368709120, -- 5 GB
  storage_used_bytes bigint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.workspace_members (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'owner' check (role in ('owner', 'admin', 'editor', 'viewer')),
  created_at timestamptz not null default now(),
  primary key (workspace_id, user_id)
);

alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;

create function public.is_workspace_member(target_workspace_id uuid)
returns boolean
language sql
security definer set search_path = public
stable
as $$
  select exists (
    select 1 from public.workspace_members
    where workspace_id = target_workspace_id and user_id = auth.uid()
  );
$$;

create policy "workspaces: members can read" on public.workspaces
  for select using (public.is_workspace_member(id));
create policy "workspaces: owner can update" on public.workspaces
  for update using (owner_id = auth.uid());
create policy "workspaces: authenticated users can create" on public.workspaces
  for insert with check (owner_id = auth.uid());
create policy "workspaces: owner can delete" on public.workspaces
  for delete using (owner_id = auth.uid());

create policy "workspace_members: members can read roster" on public.workspace_members
  for select using (public.is_workspace_member(workspace_id));
create policy "workspace_members: owner manages roster" on public.workspace_members
  for all using (
    exists (select 1 from public.workspaces w where w.id = workspace_id and w.owner_id = auth.uid())
  );

-- Auto-add the creating owner as a workspace member.
create function public.handle_new_workspace()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  insert into public.workspace_members (workspace_id, user_id, role)
  values (new.id, new.owner_id, 'owner');
  return new;
end;
$$;

create trigger on_workspace_created
  after insert on public.workspaces
  for each row execute procedure public.handle_new_workspace();

-- ---------------------------------------------------------------------------
-- clients
-- ---------------------------------------------------------------------------
create table public.clients (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  name text not null,
  email text,
  phone text,
  company text,
  notes text,
  created_at timestamptz not null default now()
);

alter table public.clients enable row level security;
create policy "clients: workspace members only" on public.clients
  for all using (public.is_workspace_member(workspace_id))
  with check (public.is_workspace_member(workspace_id));

-- ---------------------------------------------------------------------------
-- projects
-- ---------------------------------------------------------------------------
create table public.projects (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  client_id uuid references public.clients(id) on delete set null,
  name text not null,
  slug text not null,
  description text,
  project_type text not null default 'photography'
    check (project_type in ('photography','video','photo_video','automotive','wedding','event','real_estate','commercial','other')),
  project_date date,
  status text not null default 'draft' check (status in ('draft','processing','published','expired','archived')),
  cover_media_id uuid,
  vehicle_make text,
  vehicle_model text,
  vehicle_generation text,
  vehicle_year int,
  location text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, slug)
);

alter table public.projects enable row level security;
create policy "projects: workspace members only" on public.projects
  for all using (public.is_workspace_member(workspace_id))
  with check (public.is_workspace_member(workspace_id));

-- ---------------------------------------------------------------------------
-- galleries (the published, client-facing surface of a project)
-- ---------------------------------------------------------------------------
create table public.galleries (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  title text not null,
  slug text not null unique, -- public URL segment, must be unguessable
  description text,
  status text not null default 'draft' check (status in ('draft','published','unpublished')),
  password_hash text,       -- bcrypt hash, never plaintext
  password_enabled boolean not null default false,
  expiry_date timestamptz,
  downloads_enabled boolean not null default true,
  favorites_enabled boolean not null default true,
  comments_enabled boolean not null default false,
  branding_enabled boolean not null default true,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.galleries enable row level security;

create function public.workspace_id_for_project(target_project_id uuid)
returns uuid
language sql
security definer set search_path = public
stable
as $$
  select workspace_id from public.projects where id = target_project_id;
$$;

create policy "galleries: workspace members manage" on public.galleries
  for all using (public.is_workspace_member(public.workspace_id_for_project(project_id)))
  with check (public.is_workspace_member(public.workspace_id_for_project(project_id)));

-- Public, unauthenticated read of a *published, non-expired* gallery only.
-- Password-protected galleries are still readable here (metadata only) —
-- the app layer enforces password entry before revealing media.
create policy "galleries: public can read published" on public.galleries
  for select using (
    status = 'published' and (expiry_date is null or expiry_date > now())
  );

-- ---------------------------------------------------------------------------
-- gallery sections
-- ---------------------------------------------------------------------------
create table public.gallery_sections (
  id uuid primary key default gen_random_uuid(),
  gallery_id uuid not null references public.galleries(id) on delete cascade,
  title text not null,
  section_type text not null default 'grid' check (section_type in ('grid','film','reels')),
  sort_order int not null default 0
);

alter table public.gallery_sections enable row level security;

create function public.workspace_id_for_gallery(target_gallery_id uuid)
returns uuid
language sql
security definer set search_path = public
stable
as $$
  select public.workspace_id_for_project(project_id) from public.galleries where id = target_gallery_id;
$$;

create policy "gallery_sections: workspace members manage" on public.gallery_sections
