type EventProperties = Record<string, string | number | boolean>;

declare global {
  interface Window {
    dataLayer?: unknown[];
    gtag?: (...args: unknown[]) => void;
  }
}

export function trackEvent(name: RawiAnalyticsEvent, properties: EventProperties = {}) {
  if (typeof window === "undefined") return;
  window.gtag?.("event", name, properties);
}

export function markPendingProjectCreation() {
  if (typeof window === "undefined") return;
  window.sessionStorage.setItem("rawi_pending_project_created", "1");
}

export function clearPendingProjectCreation() {
  if (typeof window === "undefined") return;
  window.sessionStorage.removeItem("rawi_pending_project_created");
}

export function consumePendingProjectCreation(pathname: string) {
  if (typeof window === "undefined" || !/^\/projects\/[0-9a-f-]{36}$/i.test(pathname)) return;
  if (window.sessionStorage.getItem("rawi_pending_project_created") !== "1") return;
  clearPendingProjectCreation();
  trackEvent("project_created");
}

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import type { Database } from "@/types/database";
import { SupabaseNotConfiguredError } from "./client";

/**
 * Supabase client for Server Components, Route Handlers, and Server Actions.
 * Uses the anon key + the caller's session cookies — RLS still applies.
 * Never pass the service-role key through this helper.
 */
export async function createClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!url || !anonKey) {
    throw new SupabaseNotConfiguredError();
  }

  const cookieStore = await cookies();

  return createServerClient<Database>(url, anonKey, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) =>
            cookieStore.set(name, value, options)
          );
        } catch {
          // Called from a Server Component with no request context — the
          // middleware refresh below keeps sessions alive regardless.
        }
      },
    },
  });
}

export function isSupabaseConfigured() {
  return Boolean(
    process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY
  );
}

import { createBrowserClient } from "@supabase/ssr";
import type { Database } from "@/types/database";

/**
 * Supabase client for use in Client Components.
 * Reads publishable, browser-safe env vars only — never the service role key.
 */
export function createClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!url || !anonKey) {
    throw new SupabaseNotConfiguredError();
  }

  return createBrowserClient<Database>(url, anonKey);
}

/**
 * Thrown whenever Supabase env vars are missing so the UI can show
 * "not configured" states instead of silently faking success.
 * See RAWI spec §35 — never fake auth, uploads, or writes.
 */
export class SupabaseNotConfiguredError extends Error {
  constructor() {
    super(
      "Supabase is not configured. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in .env.local."
    );
    this.name = "SupabaseNotConfiguredError";
  }
}

import "server-only";
import { createClient as createSupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/types/database";

/**
 * Uses the service-role key. NEVER import this from a Client Component or
 * anything that ships to the browser — `server-only` enforces that at build
 * time. Used only where RLS legitimately can't express the rule, e.g.
 * issuing a signed URL for an anonymous gallery visitor.
 */
export function createAdminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !serviceKey) {
    throw new Error("Supabase admin client requires NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY.");
  }

  return createSupabaseClient<Database>(url, serviceKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
}

