"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import bcrypt from "bcryptjs";
import { createClient } from "@/lib/supabase/server";
import type { GalleryStatus } from "@/types/database";

const MAX_UPLOAD_BYTES = 500 * 1024 * 1024;
const ALLOWED_IMAGE_MIME = new Set(["image/jpeg", "image/png", "image/webp", "image/gif", "image/avif"]);
const ALLOWED_VIDEO_MIME = new Set(["video/mp4", "video/webm", "video/quicktime"]);

type AppSupabaseClient = Awaited<ReturnType<typeof createClient>>;
type WorkspacePlan = "free" | "creator" | "pro" | "studio";
type OwnedWorkspace = { id: string; plan: WorkspacePlan; storage_limit_bytes: number };

function slugify(input: string) { return input.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").slice(0, 60) || crypto.randomUUID().slice(0, 8); }
async function requireUser() { const supabase = await createClient(); const { data: { user } } = await supabase.auth.getUser(); if (!user) redirect("/login"); return { supabase, user }; }
async function getOwnedWorkspace(supabase: AppSupabaseClient, userId: string, workspaceId: string): Promise<OwnedWorkspace | null> { const { data } = await supabase.from("workspaces").select("id, plan, storage_limit_bytes").eq("id", workspaceId).eq("owner_id", userId).maybeSingle(); return data as OwnedWorkspace | null; }
async function ownsWorkspace(supabase: AppSupabaseClient, userId: string, workspaceId: string) { return Boolean(await getOwnedWorkspace(supabase, userId, workspaceId)); }
async function getOwnedProject(supabase: AppSupabaseClient, userId: string, projectId: string) { const { data } = await supabase.from("projects").select("id, workspace_id, workspaces!inner(owner_id)").eq("id", projectId).eq("workspaces.owner_id", userId).maybeSingle(); return data as { id: string; workspace_id: string } | null; }
async function getOwnedGalleryContext(supabase: AppSupabaseClient, userId: string, galleryId: string) { const { data: gallery } = await supabase.from("galleries").select("id, project_id, status, password_enabled, password_hash, downloads_enabled, favorites_enabled, comments_enabled, branding_enabled, expiry_date").eq("id", galleryId).maybeSingle(); if (!gallery) return null; const project = await getOwnedProject(supabase, userId, gallery.project_id); if (!project) return null; const workspace = await getOwnedWorkspace(supabase, userId, project.workspace_id); if (!workspace) return null; return { gallery, project, workspace }; }
async function ownsGallery(supabase: AppSupabaseClient, userId: string, galleryId: string) { return Boolean(await getOwnedGalleryContext(supabase, userId, galleryId)); }
function safeUrl(value: string): string | null | undefined { const clean = value.trim(); if (!clean) return null; const candidate = /^https?:\/\//i.test(clean) ? clean : `https://${clean}`; try { const url = new URL(candidate); if (!["http:", "https:"].includes(url.protocol) || candidate.length > 500) return undefined; return url.toString(); } catch { return undefined; } }

export async function updateSocialLinks(workspaceId: string, links: { instagram: string; tiktok: string; facebook: string; website: string; whatsapp: string }) { const { supabase, user } = await requireUser(); if (!(await ownsWorkspace(supabase, user.id, workspaceId))) return { error: "You don't have access to this workspace." }; const instagramUrl = safeUrl(links.instagram), tiktokUrl = safeUrl(links.tiktok), facebookUrl = safeUrl(links.facebook), websiteUrl = safeUrl(links.website), whatsappUrl = safeUrl(links.whatsapp); if ([instagramUrl, tiktokUrl, facebookUrl, websiteUrl, whatsappUrl].some((value) => value === undefined)) return { error: "Please enter valid http/https profile links." }; const { error } = await supabase.from("workspaces").update({ instagram_url: instagramUrl ?? null, tiktok_url: tiktokUrl ?? null, facebook_url: facebookUrl ?? null, website_url: websiteUrl ?? null, whatsapp_url: whatsappUrl ?? null }).eq("id", workspaceId).eq("owner_id", user.id); if (error) return { error: error.message }; revalidatePath("/settings"); revalidatePath("/dashboard"); revalidatePath("/g/[slug]", "page"); return { success: true }; }

export async function updateWorkspaceLogo(workspaceId: string, logoUrl: string | null) { const { supabase, user } = await requireUser(); if (!(await ownsWorkspace(supabase, user.id, workspaceId))) return { error: "You don't have access to this workspace." }; if (logoUrl !== null) { const parsed = safeUrl(logoUrl); if (!parsed || !parsed.includes("/storage/v1/object/public/public-assets/")) return { error: "Invalid workspace logo." }; logoUrl = parsed; } const { error } = await supabase.from("workspaces").update({ logo_url: logoUrl }).eq("id", workspaceId).eq("owner_id", user.id); if (error) return { error: error.message }; revalidatePath("/settings"); revalidatePath("/g/[slug]", "page"); return { success: true }; }

export async function updateGallerySettings(galleryId: string, input: { passwordEnabled: boolean; password: string; downloadsEnabled: boolean; favoritesEnabled: boolean; commentsEnabled: boolean; brandingEnabled: boolean }) { const { supabase, user } = await requireUser(); const context = await getOwnedGalleryContext(supabase, user.id, galleryId); if (!context) return { error: "You don't have access to this gallery." }; const paid = context.workspace.plan !== "free"; if (!paid && (input.passwordEnabled || input.commentsEnabled || !input.brandingEnabled)) return { error: "Client comments, password protection and custom branding require Creator or Pro." }; let passwordHash: string | null = context.gallery.password_hash; const password = input.password.trim(); if (input.passwordEnabled) { if (!context.gallery.password_enabled && !password) return { error: "Enter a password before enabling protection." }; if (password) { if (password.length < 6) return { error: "Gallery password must be at least 6 characters." }; passwordHash = await bcrypt.hash(password, 10); } } else passwordHash = null; const { error } = await supabase.from("galleries").update({ password_enabled: paid ? input.passwordEnabled : false, password_hash: paid ? passwordHash : null, downloads_enabled: input.downloadsEnabled, favorites_enabled: input.favoritesEnabled, comments_enabled: paid ? input.commentsEnabled : false, branding_enabled: paid ? input.brandingEnabled : true }).eq("id", galleryId); if (error) return { error: error.message }; revalidatePath(`/projects/${context.project.id}`); return { success: true }; }

export async function createWorkspace(formData: FormData) { const { supabase, user } = await requireUser(); const name = String(formData.get("studioName") || "").trim(); if (!name) return { error: "Studio name is required." }; const { error } = await supabase.from("workspaces").insert({ owner_id: user.id, name, slug: `${slugify(name)}-${user.id.slice(0, 6)}` }); if (error) return { error: error.message }; revalidatePath("/dashboard"); redirect("/dashboard"); }
export async function createClientRecord(workspaceId: string, formData: FormData) { const { supabase, user } = await requireUser(); if (!(await ownsWorkspace(supabase, user.id, workspaceId))) return { error: "You don't have access to this workspace." }; const name = String(formData.get("clientName") || "").trim(); if (!name) return { error: "Client name is required." }; const { data, error } = await supabase.from("clients").insert({ workspace_id: workspaceId, name, email: String(formData.get("clientEmail") || "") || undefined }).select("id").single(); return error ? { error: error.message } : { id: data.id }; }
export async function createProject(workspaceId: string, formData: FormData) { const { supabase, user } = await requireUser(); if (!(await ownsWorkspace(supabase, user.id, workspaceId))) return { error: "You don't have access to this workspace." }; const name = String(formData.get("projectName") || "").trim(); if (!name) return { error: "Project name is required." }; const clientId = String(formData.get("clientId") || "") || null; if (clientId) { const { data } = await supabase.from("clients").select("id").eq("id", clientId).eq("workspace_id", workspaceId).maybeSingle(); if (!data) return { error: "That client doesn't belong to this workspace." }; } const slug = `${slugify(name)}-${Date.now().toString(36)}`; const { data: project, error } = await supabase.from("projects").insert({ workspace_id: workspaceId, client_id: clientId, name, slug, project_type: String(formData.get("projectType") || "photography") as never }).select("id").single(); if (error) return { error: error.message }; const { data: gallery, error: galleryError } = await supabase.from("galleries").insert({ project_id: project.id, title: name, slug: `${slug}-${crypto.randomUUID().slice(0, 8)}` }).select("id").single(); if (galleryError) return { error: galleryError.message }; const { error: sectionError } = await supabase.from("gallery_sections").insert({ gallery_id: gallery.id, title: "Gallery", section_type: "grid", sort_order: 0 }); if (sectionError) return { error: sectionError.message }; revalidatePath("/projects"); redirect(`/projects/${project.id}`); }

export async function recordMediaUpload(params: { projectId: string; fileName: string; originalName: string; mimeType: string; fileSize: number; storagePath: string; thumbnailPath?: string | null; mediaType: "image" | "video" | "raw" }) { const { supabase, user } = await requireUser(); const project = await getOwnedProject(supabase, user.id, params.projectId); if (!project) return { error: "You don't have access to this project." }; const workspace = await getOwnedWorkspace(supabase, user.id, project.workspace_id); if (!workspace) return { error: "You don't have access to this workspace." }; const mime = params.mimeType.toLowerCase().trim(); const expected = ALLOWED_IMAGE_MIME.has(mime) ? "image" : ALLOWED_VIDEO_MIME.has(mime) ? "video" : null; if (!expected || params.mediaType !== expected) return { error: "This file type isn't supported." }; if (!Number.isFinite(params.fileSize) || params.fileSize <= 0 || params.fileSize > MAX_UPLOAD_BYTES) return { error: "File size is invalid or exceeds 500 MB." }; if (params.storagePath.includes("..") || params.storagePath.startsWith("/") || !params.storagePath.startsWith(`${workspace.id}/${params.projectId}/`)) return { error: "Invalid storage path." }; if (params.thumbnailPath && (expected !== "image" || params.thumbnailPath.includes("..") || params.thumbnailPath.startsWith("/") || !params.thumbnailPath.startsWith(`${workspace.id}/${params.projectId}/thumbs/`))) return { error: "Invalid thumbnail path." }; const { data: projects } = await supabase.from("projects").select("id").eq("workspace_id", workspace.id); const projectIds = (projects ?? []).map((item) => item.id); let usage = 0; if (projectIds.length) { const { data: media } = await supabase.from("media").select("file_size").in("project_id", projectIds); usage = (media ?? []).reduce((sum, item) => sum + item.file_size, 0); } if (usage + params.fileSize > workspace.storage_limit_bytes) return { error: `Storage limit reached for your ${workspace.plan.toUpperCase()} plan.` }; const { data: gallery } = await supabase.from("galleries").select("id").eq("project_id", params.projectId).limit(1).maybeSingle(); let sectionId: string | null = null; if (gallery) { const { data: section } = await supabase.from("gallery_sections").select("id").eq("gallery_id", gallery.id).limit(1).maybeSingle(); sectionId = section?.id ?? null; } const { error } = await supabase.from("media").insert({ project_id: params.projectId, gallery_section_id: sectionId, uploader_id: user.id, file_name: params.fileName, original_name: params.originalName, media_type: expected, mime_type: mime, file_size: params.fileSize, storage_path: params.storagePath, thumbnail_path: params.thumbnailPath ?? null, processing_status: expected === "video" ? "pending" : "ready" }); if (error) return { error: error.message }; await supabase.from("workspaces").update({ storage_used_bytes: usage + params.fileSize }).eq("id", workspace.id).eq("owner_id", user.id); revalidatePath(`/projects/${params.projectId}`); revalidatePath("/dashboard"); revalidatePath("/settings"); return { success: true }; }

export async function reorderProjectMedia(projectId: string, orderedIds: string[]) { const { supabase, user } = await requireUser(); const project = await getOwnedProject(supabase, user.id, projectId); if (!project) return { error: "You don't have access to this project." }; if (!orderedIds.length || new Set(orderedIds).size !== orderedIds.length) return { error: "Invalid media order." }; const { data: ownedMedia, error: fetchError } = await supabase.from("media").select("id").eq("project_id", projectId).in("id", orderedIds); if (fetchError) return { error: fetchError.message }; if ((ownedMedia ?? []).length !== orderedIds.length) return { error: "One or more media items don't belong to this project." }; for (let index = 0; index < orderedIds.length; index++) { const mediaId = orderedIds[index]; if (!mediaId) return { error: "Invalid media order." }; const { error } = await supabase.from("media").update({ sort_order: index }).eq("id", mediaId).eq("project_id", projectId); if (error) return { error: error.message }; } revalidatePath(`/projects/${projectId}`); revalidatePath("/g/[slug]", "page"); return { success: true }; }

export async function addSection(galleryId: string, title: string) { const { supabase, user } = await requireUser(); if (!(await ownsGallery(supabase, user.id, galleryId))) return { error: "You don't have access to this gallery." }; const { error } = await supabase.from("gallery_sections").insert({ gallery_id: galleryId, title }); if (error) return { error: error.message }; revalidatePath("/projects"); return { success: true }; }

export async function publishGallery(galleryId: string, publish: boolean) { const { supabase, user } = await requireUser(); const context = await getOwnedGalleryContext(supabase, user.id, galleryId); if (!context) return { error: "You don't have access to this gallery." }; if (publish && context.workspace.plan === "free" && context.gallery.status !== "published") { const { data: projects } = await supabase.from("projects").select("id").eq("workspace_id", context.workspace.id); const projectIds = (projects ?? []).map((item) => item.id); if (projectIds.length) { const { count } = await supabase.from("galleries").select("id", { count: "exact", head: true }).in("project_id", projectIds).eq("status", "published"); if ((count ?? 0) >= 3) return { error: "Free plan supports up to 3 published galleries." }; } } const status: GalleryStatus = publish ? "published" : "unpublished"; const update: { status: GalleryStatus; published_at: string | null; expiry_date: string | null } = { status, published_at: publish ? new Date().toISOString() : null, expiry_date: publish && context.workspace.plan === "free" ? new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString() : publish ? null : context.gallery.expiry_date }; const { error: galleryError } = await supabase.from("galleries").update(update).eq("id", galleryId); if (galleryError) return { error: galleryError.message }; const { error: projectError } = await supabase.from("projects").update({ status: publish ? "published" : "draft" }).eq("id", context.project.id).eq("workspace_id", context.workspace.id); if (projectError) { await supabase.from("galleries").update({ status: context.gallery.status, published_at: context.gallery.status === "published" ? new Date().toISOString() : null, expiry_date: context.gallery.expiry_date }).eq("id", galleryId); return { error: `Gallery status couldn't be synchronized: ${projectError.message}` }; } revalidatePath(`/projects/${context.project.id}`); revalidatePath("/projects"); revalidatePath("/dashboard"); return { success: true }; }

export async function updateBranding(workspaceId: string, formData: FormData) { const { supabase, user } = await requireUser(); if (!(await ownsWorkspace(supabase, user.id, workspaceId))) return { error: "You don't have access to this workspace." }; const { error } = await supabase.from("workspaces").update({ name: String(formData.get("studioName") || ""), accent_color: String(formData.get("accentColor") || "#FFD400") }).eq("id", workspaceId).eq("owner_id", user.id); if (error) return { error: error.message }; revalidatePath("/settings"); return { success: true }; }
export async function signOut() { const supabase = await createClient(); await supabase.auth.signOut(); redirect("/login"); }

