import { createHmac, timingSafeEqual } from "crypto";
import { NextRequest, NextResponse } from "next/server";
import { createAdminClient } from "@/lib/supabase/admin";

type PaidPlan = "creator" | "pro";
type ZiinaStatus =
  | "requires_payment_instrument"
  | "requires_user_action"
  | "pending"
  | "completed"
  | "failed"
  | "canceled";
type ZiinaPayment = {
  id?: string;
  status?: ZiinaStatus;
  amount?: number;
  currency_code?: string;
};
type ZiinaEvent = { event?: string; data?: ZiinaPayment };
type ActivationResult = {
  already_applied?: boolean;
  plan?: PaidPlan;
  current_period_end?: string;
};

function validSignature(payload: string, signature: string, secret: string) {
  const expected = createHmac("sha256", secret).update(payload).digest("hex");
  const expectedBuffer = Buffer.from(expected, "utf8");
  const actualBuffer = Buffer.from(signature, "utf8");
  return (
    actualBuffer.length === expectedBuffer.length &&
    timingSafeEqual(actualBuffer, expectedBuffer)
  );
}

export async function POST(request: NextRequest) {
  const webhookSecret = process.env.ZIINA_WEBHOOK_SECRET;
  const accessToken = process.env.ZIINA_ACCESS_TOKEN;
  if (!webhookSecret || !accessToken)
    return NextResponse.json(
      { error: "Ziina webhook isn't configured." },
      { status: 503 },
    );

  const payload = await request.text();
  const signature = request.headers.get("x-hmac-signature");
  if (!signature || !validSignature(payload, signature, webhookSecret))
    return NextResponse.json(
      { error: "Invalid Ziina signature." },
      { status: 400 },
    );

  let event: ZiinaEvent;
  try {
    event = JSON.parse(payload) as ZiinaEvent;
  } catch {
    return NextResponse.json({ error: "Invalid payload." }, { status: 400 });
  }
  if (event.event !== "payment_intent.status.updated" || !event.data?.id)
    return NextResponse.json({ received: true });

  // Never trust webhook money or status by itself. Re-fetch the intent from Ziina.
  const verifyResponse = await fetch(
    `https://api-v2.ziina.com/api/payment_intent/${encodeURIComponent(event.data.id)}`,
    {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    },
  );
  const payment = (await verifyResponse
    .json()
    .catch(() => ({}))) as ZiinaPayment;
  if (
    !verifyResponse.ok ||
    !payment.id ||
    payment.id !== event.data.id ||
    !payment.status
  )
    return NextResponse.json(
      { error: "Ziina payment verification failed." },
      { status: 400 },
    );

  const admin = createAdminClient();
  const { data: attempt, error: attemptError } = await admin
    .from("billing_payment_attempts")
    .select(
      "workspace_id,plan,amount,original_amount,discount_percentage,discount_redemption_id,currency_code,status,completed_at",
    )
    .eq("ziina_payment_intent_id", payment.id)
    .maybeSingle();
  if (attemptError || !attempt)
    return NextResponse.json(
      { error: "Unknown payment intent." },
      { status: 400 },
    );

  const plan = attempt.plan as PaidPlan;
  if (plan !== "creator" && plan !== "pro")
    return NextResponse.json(
      { error: "Invalid subscription plan." },
      { status: 400 },
    );
  const expectedAmount = attempt.amount;
  if (
    payment.currency_code !== "AED" ||
    payment.amount !== expectedAmount ||
    attempt.currency_code !== "AED" ||
    expectedAmount <= 0
  ) {
    return NextResponse.json(
      { error: "Payment amount doesn't match the selected plan." },
      { status: 400 },
    );
  }

  if (payment.status !== "completed") {
    const { error: statusError } = await admin
      .from("billing_payment_attempts")
      .update({ status: payment.status })
      .eq("ziina_payment_intent_id", payment.id);
    if (statusError)
      return NextResponse.json(
        { error: "Couldn't save Ziina payment status." },
        { status: 500 },
      );
    if (
      attempt.discount_redemption_id &&
      (payment.status === "failed" || payment.status === "canceled")
    ) {
      await admin
        .from("discount_redemptions")
        .update({ status: "failed" })
        .eq("id", attempt.discount_redemption_id)
        .eq("status", "reserved");
    }
    return NextResponse.json({ received: true, status: payment.status });
  }

  const { data: activation, error: activationError } = await admin.rpc(
    "activate_ziina_payment",
    { p_payment_intent_id: payment.id },
  );
  if (activationError)
    return NextResponse.json(
      { error: "Couldn't activate RAWI plan." },
      { status: 500 },
    );
  if (attempt.discount_redemption_id) {
    const { error: redemptionError } = await admin
      .from("discount_redemptions")
      .update({ status: "redeemed", redeemed_at: new Date().toISOString() })
      .eq("id", attempt.discount_redemption_id)
      .eq("status", "reserved");
    if (redemptionError)
      return NextResponse.json(
        {
          error:
            "Plan activated, but the discount record could not be finalized.",
        },
        { status: 500 },
      );
  }

  const result = activation as ActivationResult | null;
  return NextResponse.json({
    received: true,
    activated: result?.plan ?? plan,
    currentPeriodEnd: result?.current_period_end,
    alreadyApplied: result?.already_applied ?? false,
  });
}

import { createHash } from "crypto";
import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { PLAN_CONFIG } from "@/lib/plans";

type PaidPlan = "creator" | "pro";
type DiscountOffer = {
  key: string;
  percentage: 10 | 50 | 100;
  maxUses: number;
};

const DISCOUNT_OFFERS: Record<string, DiscountOffer> = {
  "8acec51e2a46aefdca51f856262ed79b56cdc67214a7bb5e69156a6568efa316": {
    key: "launch_full_2026",
    percentage: 100,
    maxUses: 5,
  },
  "81c94bf77d52f408c7b0dba23d21c4424e32c1a39d5b96a3ec9cc2bfb3ea1d0a": {
    key: "launch_half_2026",
    percentage: 50,
    maxUses: 25,
  },
  a2530c3b22691eba53bfd821403a4e69a3219643da5116e8debc02fa0dad14fa: {
    key: "launch_ten_2026",
    percentage: 10,
    maxUses: 100,
  },
};

export async function POST(request: NextRequest) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user)
    return NextResponse.json(
      { error: "Please sign in again." },
      { status: 401 },
    );

  const body = (await request.json().catch(() => null)) as {
    plan?: PaidPlan;
    workspaceId?: string;
    discountCode?: string;
  } | null;
  if (
    !body?.plan ||
    !body.workspaceId ||
    !["creator", "pro"].includes(body.plan)
  )
    return NextResponse.json(
      { error: "Invalid plan selection." },
      { status: 400 },
    );

  const { data: membership } = await supabase
    .from("workspace_members")
    .select("role")
    .eq("workspace_id", body.workspaceId)
    .eq("user_id", user.id)
    .maybeSingle();
  if (!membership || !["owner", "admin"].includes(membership.role))
    return NextResponse.json(
      { error: "You don't have permission to manage billing." },
      { status: 403 },
    );

  const plan = PLAN_CONFIG[body.plan];
  const originalAmount = plan.priceAed * 100;
  const normalizedCode = body.discountCode?.trim().toUpperCase() ?? "";
  const codeHash = normalizedCode
    ? createHash("sha256").update(normalizedCode).digest("hex")
    : "";
  const offer = normalizedCode ? DISCOUNT_OFFERS[codeHash] : undefined;
  if (normalizedCode && !offer)
    return NextResponse.json(
      { error: "This discount code is not valid." },
      { status: 400 },
    );

  const finalAmount = offer
    ? Math.round(originalAmount * (1 - offer.percentage / 100))
    : originalAmount;
  const admin = createAdminClient();
  let redemptionId: string | null = null;

  if (offer) {
    const { data, error } = await admin.rpc("claim_rawi_discount", {
      p_workspace_id: body.workspaceId,
      p_user_id: user.id,
      p_code_key: offer.key,
      p_discount_percentage: offer.percentage,
      p_max_uses: offer.maxUses,
      p_plan: body.plan,
      p_original_amount: originalAmount,
      p_final_amount: finalAmount,
    });
    if (error)
      return NextResponse.json(
        {
          error: error.message.includes("usage limit")
            ? "This code has reached its usage limit."
            : "This workspace cannot use that discount code.",
        },
        { status: 400 },
      );
    const result = data as {
      redemption_id?: string;
      activated?: boolean;
      current_period_end?: string;
    } | null;
    redemptionId = result?.redemption_id ?? null;
    if (result?.activated)
      return NextResponse.json({
        activated: true,
        discountPercentage: offer.percentage,
        currentPeriodEnd: result.current_period_end,
      });
  }

  const accessToken = process.env.ZIINA_ACCESS_TOKEN;
  if (!accessToken) {
    if (redemptionId)
      await admin
        .from("discount_redemptions")
        .update({ status: "failed" })
        .eq("id", redemptionId);
    return NextResponse.json(
      { error: "Ziina isn't connected yet.", code: "BILLING_NOT_CONFIGURED" },
      { status: 503 },
    );
  }

  const origin =
    process.env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, "") ||
    request.nextUrl.origin;
  const testMode = process.env.ZIINA_TEST_MODE === "true";
  const ziinaResponse = await fetch(
    "https://api-v2.ziina.com/api/payment_intent",
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        amount: finalAmount,
        currency_code: "AED",
        message: `RAWI ${plan.name} - 30 days${offer ? ` (${offer.percentage}% off)` : ""}`,
        success_url: `${origin}/settings?billing=success&payment_intent_id={PAYMENT_INTENT_ID}`,
        cancel_url: `${origin}/settings?billing=cancelled`,
        failure_url: `${origin}/settings?billing=failed`,
        test: testMode,
        expiry: String(Date.now() + 30 * 60 * 1000),
        allow_tips: false,
      }),
      cache: "no-store",
    },
  );
  const payment = (await ziinaResponse.json().catch(() => ({}))) as {
    id?: string;
    redirect_url?: string;
    status?: string;
    latest_error?: { message?: string };
    message?: string;
  };
  if (!ziinaResponse.ok || !payment.redirect_url || !payment.id) {
    if (redemptionId)
      await admin
        .from("discount_redemptions")
        .update({ status: "failed" })
        .eq("id", redemptionId);
    return NextResponse.json(
      {
        error:
          payment.latest_error?.message ||
          payment.message ||
          "Couldn't create Ziina checkout.",
      },
      { status: 502 },
    );
  }

  const { error: attemptError } = await admin
    .from("billing_payment_attempts")
    .insert({
      workspace_id: body.workspaceId,
      user_id: user.id,
      plan: body.plan,
      amount: finalAmount,
      original_amount: originalAmount,
      discount_percentage: offer?.percentage ?? 0,
      discount_redemption_id: redemptionId,
      currency_code: "AED",
      status:
        payment.status === "pending"
          ? "pending"
          : "requires_payment_instrument",
      ziina_payment_intent_id: payment.id,
      test_mode: testMode,
    });
  if (attemptError) {
    if (redemptionId)
      await admin
        .from("discount_redemptions")
        .update({ status: "failed" })
        .eq("id", redemptionId);
    return NextResponse.json(
      { error: "Couldn't prepare RAWI billing state. Please try again." },
      { status: 500 },
    );
  }
  if (redemptionId)
    await admin
      .from("discount_redemptions")
      .update({ ziina_payment_intent_id: payment.id })
      .eq("id", redemptionId);
  return NextResponse.json({
    url: payment.redirect_url,
    paymentIntentId: payment.id,
    testMode,
    discountPercentage: offer?.percentage ?? 0,
  });
}

import { NextRequest, NextResponse } from "next/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { PLAN_CONFIG } from "@/lib/plans";

export async function GET(request: NextRequest) {
  const cronSecret = process.env.CRON_SECRET;
  if (!cronSecret || request.headers.get("authorization") !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const admin = createAdminClient();
  const now = new Date().toISOString();
  const { data: expired, error } = await admin
    .from("subscriptions")
    .select("id,workspace_id")
    .eq("status", "active")
    .lt("current_period_end", now);

  if (error) return NextResponse.json({ error: "Couldn't load expired subscriptions." }, { status: 500 });
  if (!expired?.length) return NextResponse.json({ expired: 0 });

  let processed = 0;
  for (const subscription of expired) {
    const { error: workspaceError } = await admin
      .from("workspaces")
      .update({ plan: "free", storage_limit_bytes: PLAN_CONFIG.free.storageBytes })
      .eq("id", subscription.workspace_id);
    if (workspaceError) continue;

    const { error: subscriptionError } = await admin
      .from("subscriptions")
      .update({ status: "expired" })
      .eq("id", subscription.id)
      .eq("status", "active");
    if (!subscriptionError) processed += 1;
  }

  return NextResponse.json({ expired: processed });
}

import { NextResponse } from "next/server";

const MAX_BODY_BYTES = 64_000;

export async function POST(request: Request) {
  const startedAt = Date.now();
  const requestId = request.headers.get("x-vercel-id") ?? crypto.randomUUID();

  try {
    const contentLength = Number(request.headers.get("content-length") ?? 0);
    if (contentLength > MAX_BODY_BYTES) {
      return NextResponse.json({ ok: false }, { status: 413 });
    }

    const payload = await request.json();
    const safe = {
      level: "error",
      event: "client_error",
      requestId,
      type: String(payload?.type ?? "client-error").slice(0, 80),
      message: String(payload?.message ?? "Unknown client error").slice(0, 2000),
      stack:
        typeof payload?.stack === "string"
          ? payload.stack.slice(0, 8000)
          : undefined,
      digest:
        typeof payload?.digest === "string"
          ? payload.digest.slice(0, 200)
          : undefined,
      path:
        typeof payload?.path === "string"
          ? payload.path.slice(0, 500)
          : undefined,
      source:
        typeof payload?.source === "string"
          ? payload.source.slice(0, 500)
          : undefined,
      release:
        typeof payload?.release === "string"
          ? payload.release.slice(0, 100)
          : process.env.VERCEL_GIT_COMMIT_SHA,
      line: Number.isFinite(payload?.line) ? payload.line : undefined,
      column: Number.isFinite(payload?.column) ? payload.column : undefined,
      occurredAt:
        typeof payload?.ts === "string"
          ? payload.ts
          : new Date().toISOString(),
      userAgent:
        typeof payload?.userAgent === "string"
          ? payload.userAgent.slice(0, 500)
          : undefined,
      durationMs: Date.now() - startedAt,
    };

    console.error(JSON.stringify(safe));
    return NextResponse.json({ ok: true }, { status: 202 });
  } catch (error) {
    console.error(
      JSON.stringify({
        level: "error",
        event: "client_error_report_failed",
        requestId,
        message: error instanceof Error ? error.message : String(error),
        durationMs: Date.now() - startedAt,
      })
    );
    return NextResponse.json({ ok: false }, { status: 400 });
  }
}

