"use client";
import { useEffect, useMemo, useRef, useState } from "react";
import { getBulkDownloadUrls } from "@/app/g/[slug]/actions";
import { MediaTile } from "@/components/gallery/MediaTile";
import { ReviewPrompt } from "@/components/gallery/ReviewPrompt";
type ViewMode = "grid" | "masonry" | "large" | "slideshow";
type MediaItem = {
  id: string;
  media_type: "image" | "video" | "raw";
  signed_url?: string | null;
  thumbnail_url?: string | null;
};
type GallerySection = { id: string; title: string; media: MediaItem[] };
type Theme = "dark" | "light";
const INITIAL_VISIBLE = 24,
  LOAD_MORE = 24;
const VIEW_OPTIONS: { id: ViewMode; label: string; icon: string }[] = [
  { id: "grid", label: "Grid", icon: "▦" },
  { id: "masonry", label: "Masonry", icon: "▥" },
  { id: "large", label: "Large", icon: "▭" },
  { id: "slideshow", label: "Slideshow", icon: "▶" },
];
export function GalleryMediaGrid({
  galleryId,
  sections,
  favoritesEnabled,
  downloadsEnabled,
  commentsEnabled = false,
  theme = "dark",
  clientName,
}: {
  galleryId: string;
  sections: GallerySection[];
  favoritesEnabled: boolean;
  downloadsEnabled: boolean;
  commentsEnabled?: boolean;
  theme?: Theme;
  clientName?: string;
}) {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [downloading, setDownloading] = useState(false),
    [progress, setProgress] = useState(0),
    [message, setMessage] = useState<string | null>(null),
    [viewMode, setViewMode] = useState<ViewMode>("grid"),
    [slideIndex, setSlideIndex] = useState(0),
    [visibleCount, setVisibleCount] = useState(INITIAL_VISIBLE),
    [reviewOpen, setReviewOpen] = useState(false);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const allMedia = useMemo(() => sections.flatMap((s) => s.media), [sections]),
    allIds = useMemo(() => allMedia.map((i) => i.id), [allMedia]),
    activeSlide = allMedia.at(slideIndex) ?? null,
    light = theme === "light";
  const visibleSections = useMemo(() => {
    let remaining = visibleCount;
    return sections.map((section) => {
      const media = remaining > 0 ? section.media.slice(0, remaining) : [];
      remaining -= media.length;
      return { ...section, media };
    });
  }, [sections, visibleCount]);
  useEffect(() => {
    if (viewMode === "slideshow" || visibleCount >= allMedia.length) return;
    const node = sentinelRef.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting)
          setVisibleCount((c) => Math.min(allMedia.length, c + LOAD_MORE));
      },
      { rootMargin: "800px 0px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [viewMode, visibleCount, allMedia.length]);
  function changeView(mode: ViewMode) {
    setViewMode(mode);
    if (mode === "slideshow")
      setSlideIndex((i) => Math.min(i, Math.max(0, allMedia.length - 1)));
    if (typeof window !== "undefined")
      localStorage.setItem("rawi_gallery_view", mode);
  }
  function toggleSelected(id: string) {
    setSelected((c) => {
      const n = new Set(c);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });
    setMessage(null);
  }
  function clearSelection() {
    setSelected(new Set());
    setMessage(null);
  }
  function selectAll() {
    setSelected(new Set(allIds.slice(0, 100)));
    setMessage(
      allIds.length > 100 ? "Up to 100 files can be downloaded at once." : null,
    );
  }
  function offerReview() {
    const key = `rawi_review_prompt_${galleryId}`;
    if (sessionStorage.getItem(key)) return;
    sessionStorage.setItem(key, "1");
    window.setTimeout(() => setReviewOpen(true), 600);
  }
  async function downloadSelected() {
    if (!selected.size || downloading) return;
    setDownloading(true);
    setProgress(10);
    setMessage("Preparing secure download links…");
    try {
      const r = await getBulkDownloadUrls(galleryId, Array.from(selected));
      if ("error" in r) {
        setMessage(r.error ?? "Couldn't prepare the selected files.");
        return;
      }
      const files = r.files ?? [];
      if (!files.length) {
        setMessage("No files were available to download.");
        return;
      }
      setProgress(55);
      files.forEach((f, i) =>
        setTimeout(() => {
          const a = document.createElement("a");
          a.href = f.url;
          a.download = f.name || "download";
          a.rel = "noopener";
          document.body.appendChild(a);
          a.click();
          a.remove();
          setProgress(Math.round(55 + ((i + 1) / files.length) * 45));
        }, i * 60),
      );
      setTimeout(
        () => {
          setMessage(
            `${files.length} file${files.length === 1 ? "" : "s"} sent to your downloads.`,
          );
          setProgress(100);
          setSelected(new Set());
          offerReview();
        },
        files.length * 60 + 250,
      );
    } catch {
      setMessage("Something went wrong while preparing the download.");
    } finally {
      setTimeout(() => setDownloading(false), 400);
    }
  }
  const renderTile = (item: MediaItem, mode: ViewMode = viewMode) => (
    <MediaTile
      key={`${mode}-${item.id}`}
      mediaId={item.id}
      galleryId={galleryId}
      mediaType={item.media_type}
      initialUrl={item.signed_url}
      initialThumbnailUrl={item.thumbnail_url}
      favoritesEnabled={favoritesEnabled}
      downloadsEnabled={downloadsEnabled}
      commentsEnabled={commentsEnabled}
      initiallyFavorited={false}
      selectable={downloadsEnabled}
      selected={selected.has(item.id)}
      onToggleSelect={() => toggleSelected(item.id)}
      onDownloadComplete={offerReview}
      displayMode={mode}
    />
  );
  const labelClass = light ? "text-black/35" : "text-white/35",
    secondaryClass = light ? "text-black/45" : "text-white/45",
    inactiveViewClass = light
      ? "border-black/10 bg-white text-black/60 hover:border-black/25 hover:text-black"
      : "border-white/15 bg-white/5 text-white/70 hover:border-white/30 hover:text-white",
    sectionTitleClass = light ? "text-black" : "text-white";
  return (
    <div>
      <div
        className={`mb-6 flex flex-wrap items-center justify-between gap-4 rounded-xl ${light ? "border border-black/10 bg-white px-4 py-3" : ""}`}
      >
        <div className="flex flex-wrap items-center gap-3">
          <span
            className={`text-[10px] font-extrabold tracking-[.16em] ${labelClass}`}
          >
            VIEW
          </span>
          <div className="flex flex-wrap gap-2">
            {VIEW_OPTIONS.map((o) => (
              <button
                key={o.id}
                onClick={() => changeView(o.id)}
                className={`rounded-full border px-3.5 py-2 text-xs font-semibold ${viewMode === o.id ? "border-[#d6b600] bg-[#FFD400] text-black" : inactiveViewClass}`}
              >
                <span className="mr-1.5">{o.icon}</span>
                {o.label}
              </button>
            ))}
          </div>
        </div>
        <span className={`text-xs ${secondaryClass}`}>
          {allMedia.length} item{allMedia.length === 1 ? "" : "s"}
        </span>
      </div>
      {downloadsEnabled && (
        <div
          className={`sticky top-3 z-30 mb-7 overflow-hidden rounded-xl ${light ? "border border-black/10 bg-white/95 shadow-lg" : "border border-white/10 bg-black/85"}`}
        >
          <div className="flex flex-wrap items-center justify-between gap-3 px-4 py-3">
            <div className="flex gap-3">
              <span
                className={`text-sm font-semibold ${light ? "text-black" : "text-white"}`}
              >
                {selected.size} selected
              </span>
              <button onClick={selectAll} className="text-xs text-black/45">
                Select all
              </button>
              {selected.size > 0 && (
                <button
                  onClick={clearSelection}
                  className="text-xs text-black/45"
                >
                  Clear
                </button>
              )}
            </div>
            <button
              onClick={downloadSelected}
              disabled={!selected.size || downloading}
              className="rounded-full bg-[#FFD400] px-4 py-2 text-xs font-extrabold text-black disabled:opacity-40"
            >
              {downloading
                ? "Preparing…"
                : `Download selected${selected.size ? ` (${selected.size})` : ""}`}
            </button>
          </div>
          {downloading && (
            <div className="h-1 bg-black/5">
              <div
                className="h-full bg-[#FFD400]"
                style={{ width: `${progress}%` }}
              />
            </div>
          )}
          {message && (
            <div className="px-4 pb-3 text-xs text-black/40">{message}</div>
          )}
        </div>
      )}
      {viewMode === "slideshow" ? (
        <div className="mx-auto max-w-5xl">
          {activeSlide ? (
            renderTile(activeSlide, "slideshow")
          ) : (
            <div className="py-24 text-center">No media.</div>
          )}
          <div className="mt-4 flex justify-center gap-3">
            <button
              onClick={() =>
                setSlideIndex((i) =>
                  allMedia.length
                    ? (i - 1 + allMedia.length) % allMedia.length
                    : 0,
                )
              }
              className="rounded-full border px-5 py-2.5"
            >
              ← Previous
            </button>
            <button
              onClick={() =>
                setSlideIndex((i) =>
                  allMedia.length ? (i + 1) % allMedia.length : 0,
                )
              }
              className="rounded-full bg-black px-5 py-2.5 text-white"
            >
              Next →
            </button>
          </div>
        </div>
      ) : (
        <>
          {visibleSections.map((s, index) =>
            s.media.length ? (
              <div key={s.id} className="mb-14">
                <div className="mb-5 flex items-baseline gap-5">
                  <span className={`text-[11px] ${secondaryClass}`}>
                    {String(index + 1).padStart(2, "0")}
                  </span>
                  <h4 className={`text-2xl font-semibold ${sectionTitleClass}`}>
                    {s.title}
                  </h4>
                </div>
                {viewMode === "grid" && (
                  <div className="grid grid-cols-2 gap-3 md:grid-cols-3">
                    {s.media.map((i) => renderTile(i, "grid"))}
                  </div>
                )}
                {viewMode === "masonry" && (
                  <div className="columns-1 gap-3 sm:columns-2 md:columns-3 [&>*]:mb-3 [&>*]:break-inside-avoid">
                    {s.media.map((i) => renderTile(i, "masonry"))}
                  </div>
                )}
                {viewMode === "large" && (
                  <div className="mx-auto flex max-w-4xl flex-col gap-7">
                    {s.media.map((i) => renderTile(i, "large"))}
                  </div>
                )}
              </div>
            ) : null,
          )}
          {visibleCount < allMedia.length && (
            <div
              ref={sentinelRef}
              className={`py-8 text-center text-xs ${secondaryClass}`}
            >
              Loading more photos…
            </div>
          )}
        </>
      )}
      <ReviewPrompt
        galleryId={galleryId}
        clientName={clientName}
        open={reviewOpen}
        onClose={() => setReviewOpen(false)}
      />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { verifyGalleryPassword } from "@/app/g/[slug]/actions";

export function PasswordGate({ galleryId, title }: { galleryId: string; title: string }) {
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    startTransition(async () => {
      const result = await verifyGalleryPassword(galleryId, password);
      if ("error" in result && typeof result.error === "string") {
        setError(result.error);
        return;
      }
      window.location.reload();
    });
  }

  return (
    <main className="relative min-h-screen overflow-hidden bg-[#080808] px-6 text-white">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_18%,rgba(255,212,0,.13),transparent_25%),linear-gradient(145deg,#171717,#070707_58%,#111)]" />
      <div className="relative z-10 mx-auto flex min-h-screen max-w-md flex-col justify-between py-8">
        <header className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="grid h-10 w-10 -rotate-[8deg] place-items-center rounded-[50%_50%_50%_8px] bg-[#FFD400] font-black text-black">R</span>
            <span className="text-sm font-extrabold tracking-[.12em]">RAWI</span>
          </div>
          <span className="rounded-full border border-white/10 bg-white/[.04] px-3 py-1.5 text-[10px] font-bold tracking-[.12em] text-white/45">PRIVATE GALLERY</span>
        </header>

        <section className="py-16">
          <span className="text-[10px] font-extrabold tracking-[.18em] text-[#FFD400]">CLIENT DELIVERY</span>
          <h1 className="mt-4 text-[42px] font-semibold leading-[.95] tracking-[-.055em] sm:text-[52px]">{title}</h1>
          <p className="mt-5 max-w-sm text-sm leading-6 text-white/50">This gallery is private. Enter the password provided by the creator to continue.</p>

          <form onSubmit={handleSubmit} className="mt-8">
            <label htmlFor="gallery-password" className="mb-2 block text-[11px] font-bold uppercase tracking-[.12em] text-white/50">Gallery password</label>
            <input
              id="gallery-password"
              type="password"
              required
              autoFocus
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter password"
              className="h-14 w-full rounded-xl border border-white/15 bg-white/[.06] px-4 text-base text-white outline-none transition placeholder:text-white/25 focus:border-[#FFD400]/70 focus:bg-white/[.08]"
            />
            <div className="min-h-7 pt-2 text-sm text-red-300" role="status" aria-live="polite">{error}</div>
            <button
              type="submit"
              disabled={pending || !password.trim()}
              className="mt-2 flex h-14 w-full items-center justify-center rounded-xl bg-[#FFD400] px-5 text-sm font-extrabold text-black transition hover:brightness-105 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {pending ? "Checking…" : "Unlock gallery →"}
            </button>
          </form>
        </section>

        <footer className="text-center text-[11px] text-white/30">Secure client delivery · RAWI</footer>
      </div>
    </main>
  );
}

"use client";

import { useState, useTransition } from "react";
import { approveGalleryDelivery } from "@/app/g/[slug]/actions";

export function ClientApproval({ galleryId, initialApproval }: { galleryId: string; initialApproval: { client_name: string; approved_at: string } | null }) {
  const [approval, setApproval] = useState(initialApproval);
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const [pending, startTransition] = useTransition();

  if (approval) {
    return <section className="border-t border-black/10 bg-white px-5 py-14"><div className="mx-auto max-w-3xl rounded-[24px] border border-emerald-200 bg-emerald-50 p-7 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-full bg-emerald-600 text-xl font-black text-white">✓</div><h2 className="mt-4 text-2xl font-semibold tracking-[-.035em]">Delivery approved</h2><p className="mt-2 text-sm text-black/55">Thank you, {approval.client_name}. Your approval has been recorded.</p><p className="mt-3 text-xs font-bold uppercase tracking-[.12em] text-emerald-700">{new Intl.DateTimeFormat("en", { dateStyle: "medium", timeStyle: "short" }).format(new Date(approval.approved_at))}</p></div></section>;
  }

  function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");
    startTransition(async () => {
      const result = await approveGalleryDelivery(galleryId, name);
      if ("error" in result) {
        setError(typeof result.error === "string" ? result.error : "Couldn't record your approval. Please try again.");
        return;
      }
      setApproval({ client_name: result.clientName, approved_at: result.approvedAt });
    });
  }

  return <section className="border-t border-black/10 bg-white px-5 py-14"><div className="mx-auto max-w-3xl rounded-[24px] bg-black p-7 text-white md:p-9"><span className="text-[10px] font-extrabold tracking-[.18em] text-[#FFD400]">FINAL DELIVERY</span><h2 className="mt-3 text-3xl font-semibold tracking-[-.04em]">Everything looks good?</h2><p className="mt-3 max-w-xl text-sm leading-6 text-white/55">Confirm that you have reviewed this gallery and approve the delivered work.</p><form onSubmit={submit} className="mt-7 flex flex-col gap-3 sm:flex-row"><input required maxLength={120} value={name} onChange={(e)=>setName(e.target.value)} placeholder="Your name" className="h-12 flex-1 rounded-xl border border-white/15 bg-white/10 px-4 text-sm text-white outline-none placeholder:text-white/30 focus:border-[#FFD400]/70"/><button disabled={pending || !name.trim()} className="h-12 rounded-xl bg-[#FFD400] px-5 text-sm font-extrabold text-black disabled:opacity-50">{pending ? "Approving…" : "Approve delivery ✓"}</button></form><div className="min-h-6 pt-2 text-sm text-red-300" role="status">{error}</div><p className="mt-2 text-[11px] text-white/30">Your name and approval time will be shared with the creator.</p></div></section>;
}

"use client";

import { useState, useTransition } from "react";
import { submitGalleryReview } from "@/app/g/[slug]/actions";

export function ReviewPrompt({
  galleryId,
  clientName,
  open,
  onClose,
}: {
  galleryId: string;
  clientName?: string;
  open: boolean;
  onClose: () => void;
}) {
  const [name, setName] = useState(clientName ?? "");
  const [rating, setRating] = useState(5);
  const [review, setReview] = useState("");
  const [message, setMessage] = useState("");
  const [pending, startTransition] = useTransition();

  if (!open) return null;

  function submit(event: React.FormEvent) {
    event.preventDefault();
    setMessage("");
    startTransition(async () => {
      const result = await submitGalleryReview(galleryId, name, rating, review);
      if ("error" in result) {
        setMessage(result.error ?? "Couldn't save your review.");
        return;
      }
      setMessage("Thank you — your review was sent ✓");
      setTimeout(onClose, 900);
    });
  }

  return (
    <div
      className="fixed inset-0 z-[140] grid place-items-center bg-black/70 p-4 backdrop-blur-sm"
      onClick={onClose}
    >
      <form
        onSubmit={submit}
        onClick={(event) => event.stopPropagation()}
        className="w-full max-w-md rounded-[24px] bg-white p-6 text-black shadow-2xl"
      >
        <div className="flex items-start justify-between gap-4">
          <div>
            <span className="text-[10px] font-extrabold tracking-[.16em] text-[#b59600]">
              A QUICK REVIEW
            </span>
            <h3 className="mt-1 text-2xl font-semibold tracking-[-.03em]">
              Enjoyed your gallery?
            </h3>
            <p className="mt-2 text-sm leading-6 text-black/50">
              Your feedback helps the creator grow.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close review"
            className="grid h-9 w-9 place-items-center rounded-full bg-black/5"
          >
            ×
          </button>
        </div>
        <div
          className="mt-5 flex gap-2"
          aria-label={`${rating} out of 5 stars`}
        >
          {[1, 2, 3, 4, 5].map((star) => (
            <button
              key={star}
              type="button"
              onClick={() => setRating(star)}
              aria-label={`${star} star${star === 1 ? "" : "s"}`}
              className={`text-3xl ${star <= rating ? "text-[#FFD400]" : "text-black/15"}`}
            >
              ★
            </button>
          ))}
        </div>
        <input
          required
          maxLength={120}
          value={name}
          onChange={(event) => setName(event.target.value)}
          placeholder="Your name"
          className="mt-5 h-11 w-full rounded-xl border border-black/10 px-3 text-sm outline-none focus:border-black"
        />
        <textarea
          required
          maxLength={1000}
          rows={4}
          value={review}
          onChange={(event) => setReview(event.target.value)}
          placeholder="What did you enjoy about the experience?"
          className="mt-3 w-full resize-none rounded-xl border border-black/10 p-3 text-sm outline-none focus:border-black"
        />
        {message && (
          <p
            className={`mt-3 text-xs font-bold ${message.includes("✓") ? "text-emerald-600" : "text-red-600"}`}
          >
            {message}
          </p>
        )}
        <div className="mt-5 flex items-center justify-between gap-3">
          <button
            type="button"
            onClick={onClose}
            className="text-xs font-bold text-black/40"
          >
            Maybe later
          </button>
          <button
            disabled={pending}
            className="rounded-xl bg-black px-5 py-3 text-sm font-extrabold text-white disabled:opacity-50"
          >
            {pending ? "Sending…" : "Send review"}
          </button>
        </div>
      </form>
    </div>
  );
}

