type ClientOption = { id: string; name: string };

const PROJECT_TYPES = [
  ["photography", "Photography"],
  ["video", "Video"],
  ["photo_video", "Photo + Video"],
  ["automotive", "Automotive"],
  ["wedding", "Wedding"],
  ["event", "Event"],
  ["real_estate", "Real Estate"],
  ["commercial", "Commercial"],
  ["other", "Other"],
