export function MediaUploader({workspaceId,projectId}:{workspaceId:string;projectId:string}){const[items,setItems]=useState<UploadItem[]>([]);const[notConfigured,setNotConfigured]=useState(false);const inputRef=useRef<HTMLInputElement>(null);const jobsRef=useRef(new Map<string,UploadJob>());const activeRef=useRef(0);const queueRef=useRef<string[]>([]);
