async function finishUpload(id:string,file:File,path:string,supabase:ReturnType<typeof createClient>){const token=path.split("/").pop()?.split("-").slice(0,-1).join("-")||crypto.randomUUID();const safeName=file.name.replace(/[^a-zA-Z0-9.\-_]/g,"_");let thumbnailPath:string|null=null;const thumb=await makeThumbnail(file);if(thumb){thumbnailPath=`${workspaceId}/${projectId}/thumbs/${token}.webp`;const{error}=await supabase.storage.from("media").upload(thumbnailPath,thumb,{contentType:"image/webp",cacheControl:"31536000",upsert:false});if(error)thumbnailPath=null}const result=await recordMediaUpload({projectId,fileName:safeName,originalName:file.name,mimeType:file.type||"application/octet-stream",fileSize:file.size,storagePath:path,thumbnailPath,mediaType:mediaTypeFor(file.type||"")});if("error"in result){const cleanup=[path,...(thumbnailPath?[thumbnailPath]:[])];await supabase.storage.from("media").remove(cleanup);patchItem(id,{status:"error",message:result.error});releaseSlot(id);return}jobsRef.current.delete(id);trackEvent("media_uploaded",{media_type:mediaTypeFor(file.type||""),size_bytes:file.size});patchItem(id,{status:"done",progress:100,message:undefined});releaseSlot(id)}
async function startJob(id:string){const job=jobsRef.current.get(id);if(!job)return;let supabase;try{supabase=createClient()}catch(err){if(err instanceof SupabaseNotConfiguredError)setNotConfigured(true);patchItem(id,{status:"error",message:"Storage is not configured."});releaseSlot(id);return}const{data:{session},error}=await supabase.auth.getSession();if(error||!session?.access_token){patchItem(id,{status:"error",message:"Your session expired. Please sign in again."});releaseSlot(id);return}const supabaseUrl=process.env.NEXT_PUBLIC_SUPABASE_URL;if(!supabaseUrl){patchItem(id,{status:"error",message:"Supabase URL is not configured."});releaseSlot(id);return}const upload=new tus.Upload(job.file,{endpoint:directStorageEndpoint(supabaseUrl),retryDelays:[0,3000,5000,10000,20000],headers:{authorization:`Bearer ${session.access_token}`},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,chunkSize:TUS_CHUNK_SIZE,metadata:{bucketName:"media",objectName:job.path,contentType:job.file.type||"application/octet-stream",cacheControl:"3600"},onError:err=>{patchItem(id,{status:"error",message:err.message});releaseSlot(id)},onProgress:(uploaded,total)=>patchItem(id,{progress:total?Math.round(uploaded/total*100):0,status:"uploading",message:undefined}),onSuccess:()=>void finishUpload(id,job.file,job.path,supabase)});job.upload=upload;patchItem(id,{status:"uploading",message:undefined});try{const previous=await upload.findPreviousUploads();const previousUpload=previous[0];if(previousUpload)upload.resumeFromPreviousUpload(previousUpload);upload.start()}catch(err){patchItem(id,{status:"error",message:err instanceof Error?err.message:"Upload failed."});releaseSlot(id)}}
