if(notConfigured)return <div className="mt-4 border border-dashed border-gray-300 rounded-2xl p-6 text-center text-sm text-gray-500">Storage isn&rsquo;t configured yet. Uploads will work once Supabase credentials are set for this deployment.</div>;return <div className="mt-4"><div className="border border-dashed border-gray-300 rounded-2xl p-6 text-center flex flex-col items-center gap-2" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();uploadFiles(e.dataTransfer.files)}}><strong className="text-sm">Drop files here</strong><span className="text-xs text-gray-400">Photos • Video · up to 3 parallel resumable uploads · 500 MB each</span><button type="button" onClick={()=>inputRef.current?.click()} className="border border-gray-300 rounded-full px-4 py-2 text-sm mt-2">Select files</button><input ref={inputRef} type="file" multiple accept="image/*,video/*" className="hidden" onChange={e=>uploadFiles(e.target.files)}/></div>{items.length>0&&<ul className="mt-3 space-y-1.5">{items.map(item=><li key={item.id} className="text-xs bg-gray-50 rounded-lg px-3 py-2"><div className="flex items-center justify-between gap-3"><span className="truncate">{item.name}</span><div className="flex shrink-0 items-center gap-2"><span className={item.status==="done"?"text-green-700":item.status==="error"?"text-red-600":"text-gray-500"}>{item.status==="queued"?"Queued":item.status==="uploading"?`${item.progress}%`:item.status==="paused"?`Paused · ${item.progress}%`:item.status==="done"?"Uploaded":item.message||"Failed"}</span>{item.status==="uploading"&&<button type="button" onClick={()=>pause(item.id)} className="rounded-full border px-2.5 py-1">Pause</button>}{item.status==="paused"&&<button type="button" onClick={()=>resume(item.id)} className="rounded-full border px-2.5 py-1">Resume</button>}{item.status==="error"&&jobsRef.current.has(item.id)&&<button type="button" onClick={()=>retry(item.id)} className="rounded-full border px-2.5 py-1">Retry</button>}</div></div>{(item.status==="uploading"||item.status==="paused")&&<div className="mt-2 h-1.5 overflow-hidden rounded-full bg-gray-200"><div className="h-full bg-black transition-[width] duration-200" style={{width:`${item.progress}%`}}/></div>}</li>)}</ul>}</div>}

