"use client";

import { useState } from "react";
import { createClient } from "@/lib/supabase/client";

const MAX = 1200;
const QUALITY = 0.68;
const BATCH = 25;

async function makeThumb(blob: Blob) {
  try {
    const bitmap = await createImageBitmap(blob);
    const scale = Math.min(1, MAX / Math.max(bitmap.width, bitmap.height));
    const width = Math.max(1, Math.round(bitmap.width * scale));
    const height = Math.max(1, Math.round(bitmap.height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d", { alpha: false });
    if (!ctx) {
      bitmap.close();
      return null;
    }
    ctx.drawImage(bitmap, 0, 0, width, height);
    bitmap.close();
    return await new Promise<Blob | null>((resolve) =>
      canvas.toBlob(resolve, "image/webp", QUALITY)
    );
  } catch {
    return null;
  }
}

export function ThumbnailBackfill({
  workspaceId,
  initialPending,
}: {
  workspaceId: string;
  initialPending: number;
}) {
  const [pending, setPending] = useState(initialPending);
  const [done, setDone] = useState(0);
  const [failed, setFailed] = useState(0);
  const [running, setRunning] = useState(false);
  const [message, setMessage] = useState("");

  async function run() {
    if (running || pending === 0) return;
    setRunning(true);
    setMessage("Finding gallery images…");
    const supabase = createClient();

    try {
      const { data: projects, error: projectError } = await supabase
        .from("projects")
        .select("id")
        .eq("workspace_id", workspaceId);
      if (projectError) throw projectError;
      const ids = (projects ?? []).map((p) => p.id);
      if (!ids.length) {
        setPending(0);
        setMessage("Nothing to optimize.");
        return;
      }

      let totalDone = 0;
      let totalFailed = 0;
      let offset = 0;

      while (true) {
        const { data: media, error } = await supabase
          .from("media")
          .select("id,project_id,storage_path,thumbnail_path")
          .in("project_id", ids)
          .eq("media_type", "image")
          .order("created_at", { ascending: true })
          .range(offset, offset + BATCH - 1);
        if (error) throw error;
        if (!media?.length) break;

        for (const item of media) {
          setMessage(`Optimizing ${totalDone + totalFailed + 1} of ${initialPending} images…`);
          const { data: original, error: downloadError } = await supabase.storage
            .from("media")
            .download(item.storage_path);
          if (downloadError || !original) {
            totalFailed++;
            setFailed(totalFailed);
            continue;
          }

          const thumb = await makeThumb(original);
          if (!thumb) {
            totalFailed++;
            setFailed(totalFailed);
            continue;
          }

          const thumbPath = `${workspaceId}/${item.project_id}/thumbs/optimized-v2-${item.id}.webp`;
          const { error: uploadError } = await supabase.storage.from("media").upload(
            thumbPath,
            thumb,
            { contentType: "image/webp", cacheControl: "31536000", upsert: true }
          );
          if (uploadError) {
            totalFailed++;
            setFailed(totalFailed);
            continue;
          }

          const { error: updateError } = await supabase
            .from("media")
            .update({ thumbnail_path: thumbPath })
            .eq("id", item.id)
            .eq("project_id", item.project_id);
          if (updateError) {
            await supabase.storage.from("media").remove([thumbPath]);
            totalFailed++;
            setFailed(totalFailed);
            continue;
          }

          if (item.thumbnail_path && item.thumbnail_path !== thumbPath) {
            await supabase.storage.from("media").remove([item.thumbnail_path]);
          }

          totalDone++;
          setDone(totalDone);
          setPending((v) => Math.max(0, v - 1));
        }

        offset += media.length;
        if (media.length < BATCH) break;
      }

      setMessage(
        totalFailed
          ? `Optimized ${totalDone}. ${totalFailed} could not be processed.`
          : `All ${totalDone} gallery images optimized ✓`
      );
    } catch (err) {
      setMessage(err instanceof Error ? err.message : "Thumbnail optimization failed.");
    } finally {
      setRunning(false);
    }
  }

  return (
    <div className="rounded-[22px] border border-gray-200 bg-white p-5 md:p-6 shadow-sm">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <span className="text-[10px] font-extrabold tracking-[.16em] text-amber-600">PERFORMANCE</span>
          <h2 className="mt-1 text-xl font-bold">Optimize gallery images</h2>
          <p className="mt-1 max-w-xl text-sm leading-6 text-gray-400">
            Rebuild gallery previews as smaller 1200px WebP images for faster mobile loading. Originals are never changed.
          </p>
        </div>
        <div className="rounded-full bg-gray-100 px-3 py-2 text-xs font-bold text-gray-600">
          {pending} images
        </div>
      </div>
      <div className="mt-5 flex flex-wrap items-center gap-3">
        <button
          type="button"
          onClick={run}
          disabled={running || pending === 0}
          className="rounded-full bg-black px-5 py-3 text-sm font-extrabold text-white disabled:opacity-40"
        >
          {running ? "Optimizing…" : pending === 0 ? "All optimized" : "Optimize gallery images"}
        </button>
        {done > 0 && <span className="text-xs font-bold text-emerald-600">{done} completed</span>}
        {failed > 0 && <span className="text-xs font-bold text-red-500">{failed} failed</span>}
      </div>
      {message && <p className="mt-4 text-xs text-gray-500">{message}</p>}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { updateBranding } from "@/app/(app)/actions";
import { Field, Input, PrimaryButton, ErrorNote, SuccessNote } from "@/components/ui/form";

export function BrandingForm({
  workspaceId,
  initialName,
  initialAccent,
}: {
  workspaceId: string;
  initialName: string;
  initialAccent: string;
}) {
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  function handleSubmit(formData: FormData) {
    setError(null);
    setSuccess(false);
    startTransition(async () => {
      const result = await updateBranding(workspaceId, formData);
      if (result && "error" in result) {
        setError(result.error ?? "Something went wrong.");
        return;
      }
      setSuccess(true);
    });
  }

  return (
    <form action={handleSubmit} className="max-w-xl">
      <Field label="Studio name">
        <Input name="studioName" defaultValue={initialName} required />
      </Field>
      <Field label="Accent color">
        <div className="flex items-center gap-2 mt-2">
          <input
            type="color"
            name="accentColor"
            defaultValue={initialAccent}
            className="w-[38px] h-[38px] rounded-[10px] border border-gray-300 p-0.5"
          />
        </div>
      </Field>
      {error && <ErrorNote>{error}</ErrorNote>}
      {success && <SuccessNote>Branding updated.</SuccessNote>}
      <PrimaryButton type="submit" loading={pending} className="!w-auto px-6">Save branding</PrimaryButton>
    </form>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { publishGallery } from "@/app/(app)/actions";
import { trackEvent } from "@/lib/analytics";

export function PublishButton({ galleryId, isPublished }: { galleryId: string; isPublished: boolean }) {
  const router = useRouter();
  const [published, setPublished] = useState(isPublished);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  function toggle() {
    setError(null);
    const nextPublished = !published;
    startTransition(async () => {
      const result = await publishGallery(galleryId, nextPublished);
      if (result && "error" in result) {
        setError(result.error ?? "Something went wrong.");
        return;
      }
      setPublished(nextPublished);
      if (nextPublished) trackEvent("gallery_published");
      router.refresh();
    });
  }

  return (
    <div className="flex items-center gap-2">
      {error && <span className="text-xs text-red-600">{error}</span>}
      <button
        type="button"
        onClick={toggle}
        disabled={pending}
        className={`rounded-full px-4 py-2.5 text-sm font-extrabold disabled:opacity-60 ${
          published ? "bg-white border border-gray-300 text-black" : "bg-rawi-yellow text-black"
        }`}
      >
        {pending ? "…" : published ? "Unpublish" : "Publish"}
      </button>
    </div>
  );
}

"use client";

import { useState } from "react";

export function ShareBar({ url, clientName }: { url: string; clientName?: string }) {
  const [copied, setCopied] = useState(false);

  const message = `Hi ${clientName || "there"} \u{1F44B}\n\nYour gallery is ready.\n\nView & download your media here:\n${url}\n\nEnjoy!`;
  const whatsappHref = `https://wa.me/?text=${encodeURIComponent(message)}`;

  async function copyLink() {
    await navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div>
      <p className="text-xs text-gray-400 mb-2">Public gallery link</p>
      <code className="block bg-gray-50 border border-gray-200 rounded-lg px-3 py-2.5 text-xs break-all mb-3">{url}</code>
      <div className="flex gap-2">
        <a
          href={whatsappHref}
          target="_blank"
          rel="noopener noreferrer"
          className="flex-1 text-center bg-[#25D366] text-white font-bold rounded-full px-4 py-2.5 text-sm"
        >
          WhatsApp
        </a>
        <button
          type="button"
          onClick={copyLink}
          className="flex-1 border border-gray-300 rounded-full px-4 py-2.5 text-sm font-bold"
        >
          {copied ? "Copied!" : "Copy link"}
        </button>
      </div>
    </div>
  );
}

